// site row-level security and Project ID integrity — generated by `pnpm gen:migration` (02-architecture §4,
// 04-testing §3); SOP-DEL-02 §3 / D-18 cases added.
import { randomUUID } from 'node:crypto';
import { afterAll, beforeAll, expect, inject, it } from 'vitest';
import { createTestDatabase, type TestDatabase } from '@ocs/testing';
import {
  client,
  createDatabase,
  eq,
  inActorTransaction,
  migrateUp,
  site,
  type Database,
  type DbActor,
} from '../index.ts';

const clientA = randomUUID();
const clientB = randomUUID();
const staff: DbActor = { id: randomUUID(), kind: 'staff', clientIds: [] };
const userOfA: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientA] };
const userOfB: DbActor = { id: randomUUID(), kind: 'client', clientIds: [clientB] };
const partnerOfA: DbActor = { id: randomUUID(), kind: 'partner', clientIds: [clientA] };
const siteOf = (
  clientId: string,
  projectId: string,
  runningNo: number,
  visibility: 'internal' | 'client',
) => ({
  id: randomUUID(),
  clientId,
  projectId,
  countryCode: 'ES',
  cityCode: 'MAD',
  cityName: 'Madrid',
  runningNo,
  name: `Site ${String(runningNo).padStart(3, '0')}`,
  standard: 'L' as const,
  visibility,
});
let testDb: TestDatabase;
let database: Database;

const visibleTo = (actor: DbActor) =>
  inActorTransaction(database.db, actor, async (tx) =>
    (await tx.select().from(site)).map((r) => r.projectId).sort(),
  );

beforeAll(async () => {
  testDb = await createTestDatabase(inject('postgresUrl'));
  database = createDatabase(testDb.url);
  await migrateUp(database.pool);
  await inActorTransaction(database.db, staff, async (tx) => {
    await tx.insert(client).values([
      { id: clientA, shortCode: 'CLIENTA', name: 'Client A' },
      { id: clientB, shortCode: 'CLIENTB', name: 'Client B' },
    ]);
    await tx
      .insert(site)
      .values([
        siteOf(clientA, 'CLIENTA-ES-MAD-001', 1, 'client'),
        siteOf(clientA, 'CLIENTA-ES-MAD-002', 2, 'internal'),
        siteOf(clientB, 'CLIENTB-ES-MAD-001', 1, 'internal'),
      ]);
  });
});

afterAll(async () => {
  await database.close();
  await testDb.drop();
});

it('staff see every site', async () => {
  expect(await visibleTo(staff)).toHaveLength(3);
});

it('a client sees only its own sites marked for clients', async () => {
  expect(await visibleTo(userOfA)).toEqual(['CLIENTA-ES-MAD-001']);
  expect(await visibleTo(userOfB)).toEqual([]);
});

it('a partner sees nothing until a partner policy exists', async () => {
  expect(await visibleTo(partnerOfA)).toEqual([]);
});

it('a client cannot write', async () => {
  await expect(
    inActorTransaction(database.db, userOfA, (tx) =>
      tx.insert(site).values(siteOf(clientA, 'CLIENTA-ES-MAD-003', 3, 'client')),
    ),
  ).rejects.toThrow();
});

it('the Project ID never changes once given (SOP-DEL-02 §3, D-18)', async () => {
  await expect(
    inActorTransaction(database.db, staff, (tx) =>
      tx
        .update(site)
        .set({ projectId: 'CLIENTA-ES-MAD-099' })
        .where(eq(site.projectId, 'CLIENTA-ES-MAD-001')),
    ),
  ).rejects.toThrow();
  await expect(
    inActorTransaction(database.db, staff, (tx) =>
      tx.update(site).set({ runningNo: 9 }).where(eq(site.projectId, 'CLIENTA-ES-MAD-001')),
    ),
  ).rejects.toThrow();
  // Other fields may change.
  await inActorTransaction(database.db, staff, (tx) =>
    tx.update(site).set({ name: 'Site 001 renamed' }).where(eq(site.projectId, 'CLIENTA-ES-MAD-001')),
  );
});

it('a Project ID and a running number per client and city are unique', async () => {
  await expect(
    inActorTransaction(database.db, staff, (tx) =>
      tx.insert(site).values(siteOf(clientA, 'CLIENTA-ES-MAD-002', 7, 'internal')),
    ),
  ).rejects.toThrow();
  await expect(
    inActorTransaction(database.db, staff, (tx) =>
      tx.insert(site).values(siteOf(clientA, 'CLIENTA-ES-MAD-777', 2, 'internal')),
    ),
  ).rejects.toThrow();
});
